<div class="toolbar-row"><p class="muted">پروژه‌های قابل نمایش در پورتفولیو را مدیریت کن.</p><a class="button primary" href="<?= e(url('admin/projects/create')) ?>">＋ افزودن پروژه</a></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>عنوان</th><th>نشانی</th><th>وضعیت</th><th>ویژه</th><th></th></tr></thead><tbody><?php foreach($projects as $p): ?><tr><td><strong><?= e($p['title']) ?></strong></td><td><code><?= e($p['slug']) ?></code></td><td><span class="status <?= $p['status']==='published'?'published':'draft' ?>"><?= $p['status']==='published'?'منتشرشده':'پیش‌نویس' ?></span></td><td><?= $p['featured']?'بله':'خیر' ?></td><td class="actions"><a href="<?= e(url('admin/projects/'.$p['id'].'/edit')) ?>">ویرایش</a><form method="post" action="<?= e(url('admin/projects/'.$p['id'].'/delete')) ?>" data-confirm="پروژه حذف شود؟"><?= csrf_field() ?><button class="link-danger">حذف</button></form></td></tr><?php endforeach; ?><?php if(!$projects): ?><tr><td colspan="5"><div class="empty-state">هنوز پروژه‌ای ثبت نشده است.</div></td></tr><?php endif; ?></tbody></table></div></div>
